print("=== Cluster MOVED 重定向模拟 ===")
slot_to_node = lambda s: "nodeA" if s <= 8191 else "nodeB"
def crc16(key):
    crc = 0
    for b in key.encode('utf-8'):
        crc ^= b << 8
        for _ in range(8):
            if crc & 0x8000:
                crc = ((crc << 1) ^ 0x1021) & 0xFFFF
            else:
                crc = (crc << 1) & 0xFFFF
    return crc
def route(key, cache):
    slot = crc16(key) & 16383
    correct = slot_to_node(slot)
    guessed = cache.get(slot, correct)
    if guessed == correct:
        return "OK (在 %s 命中)" % correct
    cache[slot] = correct
    return "MOVED %d %s (刷新本地映射后重试)" % (slot, correct)
